import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Abstract Class: HandlerGroup","description":"","frontmatter":{},"headers":[],"relativePath":"api/twine/classes/HandlerGroup.md","filePath":"api/twine/classes/HandlerGroup.md"}'),n={name:"api/twine/classes/HandlerGroup.md"};function s(d,e,c,i,l,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<p><a href="./../">twine</a> / HandlerGroup</p><h1 id="abstract-class-handlergroup" tabindex="-1">Abstract Class: HandlerGroup <a class="header-anchor" href="#abstract-class-handlergroup" aria-label="Permalink to &quot;Abstract Class: HandlerGroup&quot;">​</a></h1><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L303" target="_blank" rel="noreferrer">events.ts:303</a></p><p>A group of event handlers living on a helper object the module composes, rather than as decorated methods on the module&#39;s own class.</p><p>The module discovers its groups <strong>by type</strong>: any field that is a <code>HandlerGroup</code> instance is picked up by <a href="./../functions/getEventHandlers.html">getEventHandlers</a>, its <a href="#registerhandlers">registerHandlers</a> run once, and its handlers merged into the module&#39;s tick tree - each namespaced by <a href="#ns">ns</a>, so keys stay unique across groups without the shared prototype a mixin would force. The group needs no reference to the module and the module needs no marker: it just constructs the group as a field. The framework owns the registration mechanism (where handlers attach, when they&#39;re collected, how keys are namespaced and re-armed); the group owns only the declarations.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new HandlerGroup</strong>(): <code>HandlerGroup</code></p></blockquote><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>HandlerGroup</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="ns" tabindex="-1">ns <a class="header-anchor" href="#ns" aria-label="Permalink to &quot;ns&quot;">​</a></h3><blockquote><p><code>abstract</code> <code>readonly</code> <strong>ns</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L305" target="_blank" rel="noreferrer">events.ts:305</a></p><p>This group&#39;s namespace: every key and named function is prefixed <code>${ns}/</code>.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="collect" tabindex="-1">collect() <a class="header-anchor" href="#collect" aria-label="Permalink to &quot;collect()&quot;">​</a></h3><blockquote><p><strong>collect</strong>(): <a href="./../interfaces/EventHandler.html"><code>EventHandler</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L372" target="_blank" rel="noreferrer">events.ts:372</a></p><p>This group&#39;s handlers, namespaced under <a href="#ns">ns</a> - the module-side view <a href="./../functions/getEventHandlers.html">getEventHandlers</a> merges into the tick tree. Runs <a href="#registerhandlers">registerHandlers</a> on first use.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><a href="./../interfaces/EventHandler.html"><code>EventHandler</code></a>[]</p><hr><h3 id="every" tabindex="-1">every() <a class="header-anchor" href="#every" aria-label="Permalink to &quot;every()&quot;">​</a></h3><blockquote><p><code>protected</code> <strong>every</strong>(<code>key</code>, <code>ticks</code>, <code>fn</code>, <code>opts?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L338" target="_blank" rel="noreferrer">events.ts:338</a></p><p><a href="./../functions/Every-1.html">Every</a> as a group method: run <code>fn</code> every <code>ticks</code> ticks, keyed by <code>key</code>.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="key" tabindex="-1">key <a class="header-anchor" href="#key" aria-label="Permalink to &quot;key&quot;">​</a></h5><p><code>string</code></p><h5 id="ticks" tabindex="-1">ticks <a class="header-anchor" href="#ticks" aria-label="Permalink to &quot;ticks&quot;">​</a></h5><p><code>number</code></p><h5 id="fn" tabindex="-1">fn <a class="header-anchor" href="#fn" aria-label="Permalink to &quot;fn&quot;">​</a></h5><p>(<code>c</code>) =&gt; <code>void</code></p><h5 id="opts" tabindex="-1">opts? <a class="header-anchor" href="#opts" aria-label="Permalink to &quot;opts?&quot;">​</a></h5><p><code>Omit</code>&lt;<a href="./../interfaces/OnOptions.html"><code>OnOptions</code></a>, <code>&quot;once&quot;</code> | <code>&quot;every&quot;</code>&gt; = <code>{}</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="on" tabindex="-1">on() <a class="header-anchor" href="#on" aria-label="Permalink to &quot;on()&quot;">​</a></h3><blockquote><p><code>protected</code> <strong>on</strong>(<code>key</code>, <code>detector</code>, <code>fn</code>, <code>opts?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L325" target="_blank" rel="noreferrer">events.ts:325</a></p><p>Register a handler keyed by <code>key</code> (bare - <a href="#ns">ns</a> is prepended on harvest).</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="key-1" tabindex="-1">key <a class="header-anchor" href="#key-1" aria-label="Permalink to &quot;key&quot;">​</a></h5><p><code>string</code></p><h5 id="detector" tabindex="-1">detector <a class="header-anchor" href="#detector" aria-label="Permalink to &quot;detector&quot;">​</a></h5><p><code>Detector</code></p><h5 id="fn-1" tabindex="-1">fn <a class="header-anchor" href="#fn-1" aria-label="Permalink to &quot;fn&quot;">​</a></h5><p>(<code>c</code>) =&gt; <code>void</code></p><h5 id="opts-1" tabindex="-1">opts? <a class="header-anchor" href="#opts-1" aria-label="Permalink to &quot;opts?&quot;">​</a></h5><p><a href="./../interfaces/OnOptions.html"><code>OnOptions</code></a> = <code>{}</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="rearm" tabindex="-1">rearm() <a class="header-anchor" href="#rearm" aria-label="Permalink to &quot;rearm()&quot;">​</a></h3><blockquote><p><code>protected</code> <strong>rearm</strong>(<code>ctx</code>, <code>dp</code>, <code>moduleName</code>, <code>keys?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L352" target="_blank" rel="noreferrer">events.ts:352</a></p><p>Re-arm this group&#39;s own latched handlers - the <a href="./../functions/rearmEvents.html">rearmEvents</a> a group runs on itself. Clears <code>#${moduleName}.${ns}/${key}</code> for each latched handler whose bare key is in <code>keys</code> (all latched handlers if <code>keys</code> is omitted).</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="ctx" tabindex="-1">ctx <a class="header-anchor" href="#ctx" aria-label="Permalink to &quot;ctx&quot;">​</a></h5><p><code>FunctionContext</code></p><h5 id="dp" tabindex="-1">dp <a class="header-anchor" href="#dp" aria-label="Permalink to &quot;dp&quot;">​</a></h5><p><code>Datapack</code></p><h5 id="modulename" tabindex="-1">moduleName <a class="header-anchor" href="#modulename" aria-label="Permalink to &quot;moduleName&quot;">​</a></h5><p><code>string</code></p><h5 id="keys" tabindex="-1">keys? <a class="header-anchor" href="#keys" aria-label="Permalink to &quot;keys?&quot;">​</a></h5><p>readonly <code>string</code>[]</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="registerhandlers" tabindex="-1">registerHandlers() <a class="header-anchor" href="#registerhandlers" aria-label="Permalink to &quot;registerHandlers()&quot;">​</a></h3><blockquote><p><code>abstract</code> <strong>registerHandlers</strong>(): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/CodingTwist/compiler/blob/dd975a169dae112b764e8e57237609f5867ffd23/twine/src/events.ts#L313" target="_blank" rel="noreferrer">events.ts:313</a></p><p>Declare this group&#39;s handlers with <a href="./../functions/on.html">on</a>/<a href="./../functions/every.html">every</a>. Called once, by the framework, the first time the group is harvested or re-armed - never call it yourself. It runs after the subclass constructor, so it may read fields the constructor set.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p>',77)])])}const f=a(n,[["render",s]]);export{p as __pageData,f as default};
